export const getTriggerSyncUrl = () => {




  return `/api/sync/trigger`
}

/**
 * @summary Trigger manual sync to Google Sheets
 */
export const triggerSync = async (syncTriggerInput: SyncTriggerInput, options?: RequestInit): Promise<SyncResult> => {

  return customFetch<SyncResult>(getTriggerSyncUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      syncTriggerInput,)
  }
);}




export const getTriggerSyncMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof triggerSync>>, TError,{data: BodyType<SyncTriggerInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof triggerSync>>, TError,{data: BodyType<SyncTriggerInput>}, TContext> => {

const mutationKey = ['triggerSync'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof triggerSync>>, {data: BodyType<SyncTriggerInput>}> = (props) => {
          const {data} = props ?? {};

          return  triggerSync(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type TriggerSyncMutationResult = NonNullable<Awaited<ReturnType<typeof triggerSync>>>
    export type TriggerSyncMutationBody = BodyType<SyncTriggerInput>
    export type TriggerSyncMutationError = ErrorType<unknown>

    /**
 * @summary Trigger manual sync to Google Sheets
 */
export const useTriggerSync = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof triggerSync>>, TError,{data: BodyType<SyncTriggerInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof triggerSync>>,
        TError,
        {data: BodyType<SyncTriggerInput>},
        TContext
      > => {
      return useMutation(getTriggerSyncMutationOptions(options));
    }

